function renderToolList(pack, ix) {
  const e = ledgerEsc;
  return pack.toolSlugs
    .map((slug) => {
      const t = ix.get(slug);
      if (!t) {
        return `<li><span class="row"><span class="name">${e(slug)}</span> <span class="missing">-- tool not currently in catalog</span></span></li>`;
      }
      // No per-member price here. This page sells the BUNDLE (one call, one
      // payment, priced above); a column of member prices next to it read as
      // an itemised bill for buying the parts separately instead - pricing
      // advice against the product the page exists to sell. Each member's own
      // price is one click away on its tool page, and /api/pricing carries
      // every price for agents that need them.
      return `<li>
  <span class="row">
    <span class="name"><a href="/tools/${e(slug)}">${e(t.name)}</a></span>
    <span class="route">${e(t.route)}</span>
  </span>
  <span class="desc">${e(t.description)}</span>
</li>`;
    })
    .join("\n");
}

export function skillPackPage(baseUrl, slug, catalog) {
  const e = ledgerEsc;
  const pack = SKILL_PACKS.find((p) => p.slug === slug);
  if (!pack) return null;
  const ix = indexCatalog(catalog);
  const tools = renderToolList(pack, ix);
  const steps = pack.workflow.map((s) => `<li>${e(s)}</li>`).join("\n");
  // The pack's OWN endpoint, read from the served catalog so the page can never
  // quote a price the server doesn't charge. Absent only if the pack has no
  // bundled route registered, in which case the block is skipped rather than
  // rendered empty.
  const packTool = ix.get(`skill-${pack.slug}`);

  const jsonLd = {
    "@context": "https://schema.org",
    "@type": "HowTo",
    name: pack.title,
    description: pack.tagline,
    url: `${baseUrl}/skills/${pack.slug}`,
    step: pack.workflow.map((s, i) => ({
      "@type": "HowToStep",
      position: i + 1,
      text: s,
    })),
  };

  const body = `<div style="max-width:1180px;margin:0 auto;padding:56px 30px;">
<h1 style="font-family:var(--font-body);font-weight:800;font-size:38px;line-height:1;letter-spacing:-.02em;margin-bottom:10px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;text-overflow:ellipsis;" title="${e(pack.title)}">${e(pack.title)}</h1>
<p style="color:var(--muted);font-size:16px;line-height:1.6;max-width:720px;">${e(pack.tagline)}</p>
${packTool ? `
<div class="sk-buy">
  <div class="sk-buy-head">
    <span class="sk-buy-price">${e(packTool.price)}</span>
    <span class="sk-buy-unit">per call &middot; one payment for the whole workflow</span>
  </div>
  <div class="sk-buy-route">${e(packTool.route)}</div>
  <p class="sk-buy-note">${pack.toolSlugs.length} tools run server-side in one request. You pay once, settle once, and get a single response - no orchestration, no per-step payments, and a partial-success envelope if any step fails. USDC over x402 on any supported chain.</p>
</div>` : ""}

<h2 style="font-weight:800;font-size:22px;margin-top:40px;letter-spacing:-.01em;">When to use this pack</h2>
<p style="color:var(--muted);font-size:15px;line-height:1.7;">${e(pack.useCase)}</p>

<h2 style="font-weight:800;font-size:22px;margin-top:40px;letter-spacing:-.01em;">Tools in this pack</h2>
<p style="color:var(--muted);font-size:14.5px;line-height:1.7;margin:0 0 4px;">${packTool ? `All ${pack.toolSlugs.length} run inside the single ${e(packTool.price)} call above.` : `The ${pack.toolSlugs.length} tools this workflow composes.`} Each is also callable on its own if you only need one part.</p>
<ul class="sk-tl">${tools}</ul>

<h2 style="font-weight:800;font-size:22px;margin-top:40px;letter-spacing:-.01em;">Workflow</h2>
<ol class="sk-wf">${steps}</ol>

${packTool ? `
<h2 style="font-weight:800;font-size:22px;margin-top:40px;letter-spacing:-.01em;">Call it directly</h2>
<p style="color:var(--muted);font-size:15px;line-height:1.7;">Any x402 client pays the 402 and gets the whole workflow back in one response:</p>
<pre style="background:var(--surface);color:var(--on-dark);font-family:var(--font-mono);padding:18px 20px;font-size:13px;line-height:1.6;border:none;margin-top:12px;overflow-x:auto;">npx agent402-client call ${e(pack.slug)} ${e(JSON.stringify(Object.fromEntries((pack.promptArgs || []).map((a) => [a.name, a.substitute ?? "..."]))))}</pre>` : ""}

<h2 style="font-weight:800;font-size:22px;margin-top:40px;letter-spacing:-.01em;">Run it in Claude</h2>
<pre style="background:var(--surface);color:var(--on-dark);font-family:var(--font-mono);padding:18px 20px;font-size:13px;line-height:1.6;border:none;margin-top:12px;">claude mcp add agent402 -s user -- npx -y agent402-mcp@latest</pre>
<p style="color:var(--muted);font-size:15px;margin-top:12px;">Then paste this prompt into Claude:</p>
<div class="sk-prompt"><pre>${e(pack.claudePrompt)}</pre></div>

<p style="color:var(--faint);font-size:14px;margin-top:36px;"><a href="/skills" style="color:var(--accent);text-decoration:none;">\u2190 All skill packs</a></p>
</div>
${ledgerFooterCompact()}`;

  return ledgerShell({
    title: `${pack.title} -- Agent402 skill pack`,
    description: pack.tagline,
    canonical: `${baseUrl}/skills/${pack.slug}`,
    baseUrl,
    activePath: "/skills",
    jsonLd,
    extraCss: SKILLS_CSS,
    body,
  });
}

export const skillSlugs = () => SKILL_PACKS.map((p) => p.slug);

// Machine-readable shape served at /api/skill-packs.json — also what the
// stdio agent402-mcp npm package fetches at startup to register its prompts.
// We strip internal-only fields like `substitute` (a render hint) and expose
// the public schema that any MCP client or discovery aggregator needs.
export function skillPacksJson() {
  return {
    packs: SKILL_PACKS.map((p) => ({
      slug: p.slug,
      title: p.title,
      tagline: p.tagline,
      useCase: p.useCase,
      toolSlugs: p.toolSlugs,
      workflow: p.workflow,
      claudePrompt: p.claudePrompt,
      promptArgs: (p.promptArgs || []).map((a) => ({
        name: a.name,
        description: a.description,
        required: a.required ?? true,
      })),
    })),
  };
}

// Build an MCP prompt response for a skill pack — `messages` array + a top-level
// `description`. Two design choices baked in here, both Option-A from the
// trade-off matrix:
//   1. We name the exact tool slug at each step so the agent doesn't have to
//      search the catalog first (deterministic; fewer round-trips).
//   2. We pre-split the tool list into "free here" vs "wallet required" so the
//      agent can short-circuit before getting a 402 — `freeSlugs` is computed
//      per-session in mcp-http.js's buildServer().
// `args` is the MCP-prompt arguments object the client passes (e.g.
// `{ domain: "stripe.com" }`). For each entry in `pack.promptArgs` that
// declares a `substitute` string, we replace literal occurrences of that
// string in the prompt body — keeps the existing example-driven claudePrompt
// reusable as a template without introducing curly-brace placeholders that
// would leak into the HTML render.
export function buildPromptMessages(pack, args = {}, { freeSlugs } = {}) {
  let body = pack.claudePrompt;
  let useCase = pack.useCase;
  for (const a of pack.promptArgs || []) {
    const v = args && args[a.name];
    if (v && a.substitute) {
      body = body.split(a.substitute).join(String(v));
      useCase = useCase.split(a.substitute).join(String(v));
    }
  }

  const freeSet = freeSlugs instanceof Set ? freeSlugs : null;
  const free = [];
  const wallet = [];
  for (const slug of pack.toolSlugs) {
    if (!freeSet) continue;
    (freeSet.has(slug) ? free : wallet).push(slug);
  }

  // Per-step plan: if the workflow narrative and toolSlugs are 1:1, zip them
  // so the agent sees "step N → call this slug". Otherwise (e.g. security-audit
  // has one extra tool covered by a multi-tool step) list them in parallel
  // sections so we don't misalign instructions and tools.
  let plan;
  if (pack.toolSlugs.length === pack.workflow.length) {
    plan = pack.workflow
      .map((w, i) => `${i + 1}. call_tool { slug: "${pack.toolSlugs[i]}" } - ${w}`)
      .join("\n");
  } else {
    plan = [
      "Tools (in order):",
      ...pack.toolSlugs.map((s, i) => `  ${i + 1}. ${s}`),
      "",
      "Workflow:",
      ...pack.workflow.map((w, i) => `  ${i + 1}. ${w}`),
    ].join("\n");
  }

  const accessLines = [];
  if (free.length)
    accessLines.push(`Free on this hosted connector (compute-only, rate-limited): ${free.join(", ")}`);
  if (wallet.length)
    accessLines.push(
      `Wallet required (USDC via x402): ${wallet.join(", ")}. ` +
        `For paid access, use the agent402-mcp npm server with AGENT_KEY set, or call over HTTP with any x402 client.`
    );

  // Lead with the BUNDLE. This prompt used to open with the per-step plan,
  // which told the agent to make one paid call per tool - more round-trips for
  // the agent, more settlements to sign, and it routed around the single
  // bundled endpoint that exists to do exactly this. The per-step plan stays
  // as the fallback for a client that cannot reach the bundled route (and it
  // is what the free compute-only tier can still run).
  const bundledSlug = `skill-${pack.slug}`;
  const text = [
    body,
    "",
    "---",
    "",
    `Context - ${pack.title}: ${useCase}`,
    "",
    "Preferred - run the whole workflow in ONE paid call:",
    "",
    `  call_tool { slug: "${bundledSlug}" }`,
    "",
    `All ${pack.toolSlugs.length} steps run server-side and come back in a single response, so this is one payment and one settlement instead of ${pack.toolSlugs.length}. Partial failures come back in the envelope rather than losing the run.`,
    "",
    "Fallback - if that route is unavailable to your client, run the steps yourself:",
    "",
    plan,
    ...(accessLines.length ? ["", "Access:", ...accessLines] : []),
  ].join("\n");

  return {
    description: `${pack.title}: ${pack.tagline}`,
    messages: [{ role: "user", content: { type: "text", text } }],
  };
}

// Lexical ranker for skill packs, mirroring the one in find.js so /api/find and
// the MCP search_tools surface can recommend a *workflow* when the agent's query
// matches a multi-tool task (e.g. "audit a domain" → security-audit) instead of
// just returning the best individual tool. Scoring stays modest so packs only
// rank alongside tools when the lexical signal is strong:
//   slug exact match           = 12  (a pack is a richer answer than a single tool)
//   slug substring             =  5
//   title substring            =  3
//   tagline substring          =  2
//   useCase substring          =  1
//   tool slug in pack.toolSlugs =  4 ("check spf" → email-deliverability via spf-check)
//   workflow narrative hit     =  1
const PACK_STOPWORDS = new Set([
  "a", "an", "the", "of", "in", "on", "to", "for", "with", "by", "and", "or",
  "is", "are", "was", "were", "be", "been", "this", "that", "it", "as", "at",
  "from", "into", "onto", "my", "me", "i", "you", "your", "we", "our",
  "do", "does", "did", "can", "will", "would", "should",
]);

// `toolPriceUsd(slug) -> number|null` lets a caller that holds the live CATALOG
// (find.js, the MCP connector) hand us real per-tool prices so each
// recommendation can state what the same work costs a la carte.
//
// That comparison is NOT decoration. Measured across the catalog, 99 of 102
// packs cost MORE than calling their tools individually — several by 12-30x —
// because a pack is priced for orchestration, one round trip and one
// settlement, not as a volume discount. Recommending the bundle harder while
// staying quiet about that would be an upsell dressed as an answer, and an
// agent that later does the arithmetic is precisely the buyer we would lose.
// So we surface both numbers and let the caller choose.
export function rankSkillPacks(query, { k = 2, baseUrl = "", minScore = 4, toolPriceUsd = null } = {}) {
  const q = String(query || "").slice(0, 500);
  const rawTerms = q.toLowerCase().split(/[^a-z0-9]+/).filter(Boolean);
  const terms = rawTerms.filter((t) => t.length > 1 && !PACK_STOPWORDS.has(t)).slice(0, 32);
  if (!terms.length) return [];

  const scored = [];
  for (const pack of SKILL_PACKS) {
    const slug = pack.slug.toLowerCase();
    const title = (pack.title || "").toLowerCase();
    const tagline = (pack.tagline || "").toLowerCase();
    const useCase = (pack.useCase || "").toLowerCase();
    const toolSet = new Set((pack.toolSlugs || []).map((s) => String(s).toLowerCase()));
    const workflowHay = (pack.workflow || []).join(" ").toLowerCase();
    let score = 0;
    for (const term of terms) {
      if (slug === term) score += 12;
      else if (slug.includes(term)) score += 5;
      if (title.includes(term)) score += 3;
      if (tagline.includes(term)) score += 2;
      if (useCase.includes(term)) score += 1;
      if (toolSet.has(term)) score += 4;
      if (workflowHay.includes(term)) score += 1;
    }
    if (score >= minScore) scored.push([score, pack]);
  }
  scored.sort((a, b) => b[0] - a[0] || a[1].slug.length - b[1].slug.length || a[1].slug.localeCompare(b[1].slug));

  return scored.slice(0, Math.min(Math.max(k, 1), SKILL_PACKS.length)).map(([score, p]) => {
    const price = PACK_PRICES[p.slug] ?? 0.05;
    const priceLabel = `$${fmtPackUsd(price)}`; // whole milli-dollars: the derived price is charged as derived, never rounded to a cent
    // Only claim an a la carte total when EVERY step resolves to a real price.
    // A partial sum would understate the alternative and quietly flatter the
    // bundle, which is the one thing this comparison exists to prevent.
    let aLaCarte = null;
    if (typeof toolPriceUsd === "function") {
      let sum = 0, ok = true;
      for (const t of p.toolSlugs || []) {
        const v = toolPriceUsd(t);
        if (typeof v !== "number" || !Number.isFinite(v)) { ok = false; break; }
        sum += v;
      }
      if (ok && (p.toolSlugs || []).length) aLaCarte = sum;
    }
    return {
      slug: p.slug,
      title: p.title,
      tagline: p.tagline,
      toolSlugs: p.toolSlugs,
      score,
      url: baseUrl ? `${baseUrl}/skills/${p.slug}` : `/skills/${p.slug}`,
      promptName: p.slug, // matches the MCP prompts/list name; agents can prompts/get this directly
      // THE ONE-CALL PURCHASE. Everything above describes a workflow; without
      // these three fields the only actionable thing we handed back was
      // promptName, which means "orchestrate it yourself" — the agent then runs
      // every underlying tool and pays for each. The bundled endpoint has
      // existed the whole time and was simply never named at the point of
      // recommendation, so the cheaper, single-payment path was invisible
      // exactly where an agent was deciding what to do.
      method: "POST",
      route: `/api/skill/${p.slug}`,
      callUrl: baseUrl ? `${baseUrl}/api/skill/${p.slug}` : `/api/skill/${p.slug}`,
      price: priceLabel,
      // Name the trade-off rather than just the headline: the bundle is one
      // payment, one round trip and partial-success handling, but for almost
      // every pack the same tools cost less bought individually. Stating both
      // is what makes this a recommendation instead of an upsell.
      ...(aLaCarte == null ? {} : { aLaCarteUsd: Number(aLaCarte.toFixed(4)) }),
      oneCall:
        `POST ${baseUrl}/api/skill/${p.slug} runs all ${p.toolSlugs.length} steps for one ${priceLabel} payment ` +
        `(partial success per step).` +
        (aLaCarte == null
          ? ` Calling the ${p.toolSlugs.length} tools individually also works and bills separately.`
          : ` The same ${p.toolSlugs.length} tools bought individually total $${aLaCarte.toFixed(3)}` +
            (aLaCarte < price
              ? ` — cheaper a la carte; the bundle buys one payment, one round trip and partial-success handling.`
              : ` — the bundle is also the cheaper path.`)),
    };
  });
}
